const pause=ms=>new Promise(r=>setTimeout(r,ms));
function distanceReference(){return typeof netRoom!=='undefined'&&netRoom?.memberId?state.players.find(p=>p.memberId===netRoom.memberId)??current():current()}
function tileDistances(reference=distanceReference()){
 const n=state.tiles.length,distances=Array(n).fill(null);distances[reference.pos]=0;let count=0;
 for(let step=1;step<n;step++){const pos=(reference.pos+step)%n;if(pos!==0&&state.players.some(p=>p!==reference&&p.pos===pos))continue;distances[pos]=++count}
 return distances;
}
function distanceBadge(distance,x,y,size){const label=distance===null?'—':String(distance),description=distance===null?'有其他玩家在格，不计入':distance===0?'当前所在格':`距当前位置${distance}格`;return `<g class="tile-distance" pointer-events="none" aria-label="${description}"><title>${description}</title><rect x="${x-13}" y="${y-size/2+6}" width="26" height="13" rx="6" fill="#fffdf7" stroke="#b8c6ad" stroke-width=".7"/><text x="${x}" y="${y-size/2+16}" text-anchor="middle" font-size="10" font-weight="700" fill="${distance===null?'#899382':'#275c48'}">${label}</text></g>`}
function pawnScale(size){return size*.055}
function boardPaddingFor(players,size){const largestStack=Math.max(1,...players.map(p=>players.filter(q=>q.pos===p.pos).length)),scale=pawnScale(size),pawnEdge=(largestStack-1)*scale*8/3+4*scale+8;return Math.max(0,size/2+42-85,pawnEdge-85)}
function boardCardSize(n){return 830/Math.ceil(n/4)*.98}
function boardPoint(pos,n){let index=((pos%n)+n)%n;const corners=[[85,85],[915,85],[915,915],[85,915],[85,85]];for(let side=0;side<4;side++){const count=Math.floor(n/4)+(side<n%4?1:0);if(index<count){const t=index/count;return corners[side].map((v,axis)=>v+(corners[side+1][axis]-v)*t)}index-=count}return corners[0]}
function showJumpPoints(m){if(m.backward||!m.jumpedPlayers?.length)return;const p=state?.players[m.player];if(!p)return;const points=m.jumpedPlayers.length*happinessGain(p,jumpReward(p));$('jumpPoints').innerHTML=`<div class="jump-points-popup"><small>${esc(p.name)}・跳过奖励！</small><strong>+${points}P</strong></div>`}
function playMovementSound(m,ticket=epoch){if(m.flight)playSound('escapeFlight');else if(m.jumpedPlayers?.length){playSound('jump');setTimeout(()=>{if(ticket===epoch&&!m.backward){playSound('points');showJumpPoints(m)}},260)}else playSound('knock')}
async function animateAdvance(p,steps,ticket){for(let i=0;i<steps;i++){if(ticket!==epoch)return false;const from=p.pos;advance(p,1,steps-i-1);const {path,jumpedPlayers,stopTraps}=state.lastMove;state.motion={player:state.players.indexOf(p),from,to:p.pos,path,jumpedPlayers,jumped:jumpedPlayers.length>0};playMovementSound(state.motion,ticket);render();await pause(jumpedPlayers.length?340:240);if(ticket!==epoch)return false;state.motion=null;if(stopTraps.length){if(!await animateStopTraps(p,stopTraps,ticket))return false;if(!state.traps?.some(t=>t.tileId===state.tiles[p.pos].id))win(p);break}if(i===steps-1&&!stopTraps.length&&!await animateFraudDisarm(p,ticket))return false;if(state.winner||state.trapVictoryPending||p.pos===0)break}return true}
async function animateReturn(p,ticket){const from=p.pos;p.pos=0;state.motion={player:state.players.indexOf(p),from,to:0};playSound('knock');render();await pause(280);if(ticket!==epoch)return false;state.motion=null;return true}
