function rollForwardDie(g,p,r){if(p.character!=='nadeshiko'||diceCount(p)!==1||p.forced!=null||effectiveDieRange(p)!==6)return rollDie(p,r);const lucky=[];for(let face=1;face<=6;face++){let pos=p.pos,stopped=false;for(let step=0;step<face&&!stopped;step++)for(let guard=0;guard<g.tiles.length;guard++){pos=(pos+1)%g.tiles.length;if(pos===0){stopped=true;break}const occupied=g.players.some(q=>q!==p&&q.pos===pos),passing=step<face-1||occupied,blocked=passing&&(g.frauds??[]).some(t=>t.tileId===g.tiles[pos].id&&('ownerMemberId' in t?t.ownerMemberId!==p.memberId:t.owner!==g.players.indexOf(p)));if(blocked){stopped=true;break}if(!occupied)break}if(['good','item','refresh'].includes(g.tiles[pos].event[3]))lucky.push(face)}return lucky.length?lucky[r(lucky.length)]:rollDie(p,r)}
