function initItems(){state.itemDeck=shuffled(items.flatMap((_,id)=>Array(state.players.length).fill(id)));state.itemDiscard=[]}
function drawItem(p){if(!state.itemDeck)initItems();if(!state.itemDeck.length){state.itemDeck=shuffled(state.itemDiscard);state.itemDiscard=[]}if(!state.itemDeck.length){log('道具牌堆已空，本次不发放。');return false}p.hand.push(state.itemDeck.pop());return true}
