function handOwner(){return state.players[controlIndex()]}
function checkHandLimit(resumePhase){const index=state.players.map((_,i)=>(state.turn+i)%state.players.length).find(i=>state.players[i].hand.length>handLimit(state.players[i]));if(index===undefined){delete state.discardPlayer;if(state.phase==='discard')state.phase=resumePhase;return false}state.afterDiscard=resumePhase;state.discardPlayer=index;state.phase='discard';log(`${state.players[index].name}的手牌为${state.players[index].hand.length}张。请弃牌至${handLimit(state.players[index])}张以下。`);return true}

