 let distance=0;for(let pos=(p.pos+1)%g.tiles.length;;pos=(pos+1)%g.tiles.length){if(pos===0){distance++;break}if(!g.players.some(q=>q!==p&&q.pos===pos))distance++}
 const next={...p};if(kind==='double'||kind==='sprint')next.nextDice=kind==='double'?2:3;else{resetDiceValue(next);if(kind==='alcohol')next.nextRange=12;else next.forced=kind==='six'?6:kind==='selfChoose'?5:8}
 const progress=q=>{const tickets=q.forced!=null?1:q.character==='chihiro'&&effectiveDieRange(q)===6?12:effectiveDieRange(q),faces=Array.from({length:tickets},(_,i)=>rollDie(q,()=>i));let probabilities=Array(distance+1).fill(0);probabilities[0]=1;for(let die=0;die<diceCount(q);die++){const result=Array(distance+1).fill(0);for(let at=0;at<=distance;at++)for(const face of faces)result[Math.min(distance,at+face)]+=probabilities[at]/faces.length;probabilities=result}return probabilities.reduce((sum,chance,at)=>sum+chance*at,0)};
