function takeStopTraps(p,passing){if(!passing||p.pos===0)return [];const index=state.players.indexOf(p),tileId=state.tiles[p.pos].id,caught=(state.frauds??[]).filter(t=>t.tileId===tileId&&t.owner!==index);state.frauds=(state.frauds??[]).filter(t=>!caught.includes(t));return caught}
