  for(let guard=0;guard<state.tiles.length;guard++){
   p.pos=(p.pos+1)%state.tiles.length;path.push(p.pos);
   if(p.pos===0){p.laps++;crossed=true;log(`${p.name}到达第${p.laps}圈终点！`)}
   if(p.pos===0)break;
   const occupants=state.players.map((q,j)=>({q,j})).filter(({q})=>q!==p&&q.pos===p.pos);
   stopTraps=takeStopTraps(p,i<steps-1||remainingAfter>0||occupants.length>0);if(stopTraps.length)break;
   if(!occupants.length)break;
   occupants.forEach(({q,j})=>{adjustScore(p,jumpReward(p));jumpedPlayers.push(j);log(`${p.name}跳过了${q.name}。${p.name}幸福 +${happinessGain(p,jumpReward(p))}P。`)});
  }
  state.lastMove={path,jumpedPlayers,stopTraps};if(stopTraps.length)return;
  if(crossed)return;
